    H=len(g);W=len(g[0]);seen=set();res=[]
    for r in range(H):
        for c in range(W):
            if g[r][c]==val and (r,c) not in seen:
                st=[(r,c)];comp=[]
                while st:
                    a,b=st.pop()
                    if (a,b) in seen: continue
