def comps(g,col,conn=8):
    H=len(g);W=len(g[0]);seen=set();res=[]
    for i in range(H):
        for j in range(W):
            if g[i][j]==col and (i,j) not in seen:
                st=[(i,j)];cells=[]
                while st:
                    a,b=st.pop()
                    if (a,b) in seen:continue
                    seen.add((a,b));cells.append((a,b))
                    for da in(-1,0,1):
                        for db in(-1,0,1):
                            x,y=a+da,b+db
                            if 0<=x<H and 0<=y<W and g[x][y]==col and (x,y) not in seen: st.append((x,y))
                res.append(cells)
    return res
